import { PageHeader } from '@kerfjs/ui/page-header';
import { StateBanner } from '@kerfjs/ui/state-banner';
import { EmptyState } from '@kerfjs/ui/empty-state';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import '@kerfjs/ui/layout.css';

export type Item = { id: string; title: string };
export type ListState = {
  // null means no successful response yet; [] is a successful empty response.
  data: readonly Item[] | null;
  pending: boolean;
  error: string | null;
};
export function ListWorkspace({ state, refresh, create }: {
  state: ListState; refresh: () => void; create: () => void;
}) {
  const initialLoading = state.pending && state.data === null;
  const refreshing = state.pending && state.data !== null;
  return <main className="kui-layout" aria-labelledby="workspace-title">
    <PageHeader title={<span id="workspace-title">Projects</span>} />
    <section className="kui-pane" aria-label="Project list">
      <div role="status" aria-live="polite">
        {initialLoading && <><LoadingSpinner aria-hidden="true" /> Loading projects…</>}
        {refreshing && <><LoadingSpinner aria-hidden="true" /> Refreshing projects. Showing the last available results.</>}
      </div>
      {state.error && <div role="alert">
        <StateBanner variant="danger" title="Could not load projects">
          <p>{state.error}</p>
          {state.data !== null && <p>The last available results are still shown below.</p>}
          <button type="button" disabled={state.pending} onClick={refresh}>Retry</button>
        </StateBanner>
      </div>}
      <div aria-busy={state.pending}>
        {state.data !== null && state.data.length === 0 &&
          <EmptyState title="No projects yet" description="Create a project to get started.">
            <button type="button" onClick={create}>Create project</button>
          </EmptyState>}
        {state.data !== null && state.data.length > 0 &&
          <ul>{state.data.map(item => <li key={item.id}>{item.title}</li>)}</ul>}
      </div>
      {state.data !== null && <button type="button" disabled={state.pending} onClick={refresh}>Refresh</button>}
    </section>
  </main>;
}

