import type { Item, ListState } from './ListWorkspace';
export function createListController(fetchItems: () => Promise<Item[]>, changed: (state: ListState) => void) {
  let state: ListState = { data: null, pending: false, error: null };
  let generation = 0;
  let disposed = false;
  const publish = () => { if (!disposed) changed(state); };
  return {
    async refresh() {
      const request = ++generation;
      state = { ...state, pending: true, error: null };
      publish();
      try {
        const data = await fetchItems();
        if (disposed || request !== generation) return;
        state = { data, pending: false, error: null };
      } catch {
        if (disposed || request !== generation) return;
        state = { ...state, pending: false, error: 'Check your connection and try again.' };
      }
      publish();
    },
    dispose() { disposed = true; generation++; },
  };
}
